package admin

import (
	"bytes"
	"encoding/json"
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/Wei-Shaw/sub2api/internal/service"
)

const modelCapabilityDefaultsKey = "model_capability_defaults"

// AccountModelCapabilityDefaults is an account-scoped deployment statement, not
// an authorization or an override of native upstream evidence. Identity fields
// and confirmation attribution are generated by the handler, never trusted as
// user assertions. Clearing the extra value with null removes the statement.
type AccountModelCapabilityDefaults struct {
	SchemaVersion       int                                   `json:"schema_version"`
	Reason              string                                `json:"reason"`
	Models              map[string]AccountModelCapabilitySpec `json:"models"`
	ConfirmedBy         string                                `json:"confirmed_by,omitempty"`
	ConfirmedAt         string                                `json:"confirmed_at,omitempty"`
	IdentityRevision    string                                `json:"identity_revision,omitempty"`
	IdentityFingerprint string                                `json:"identity_fingerprint,omitempty"`
}

type AccountModelCapabilitySpec struct {
	DisplayName             string                     `json:"display_name,omitempty"`
	TaskType                string                     `json:"task_type,omitempty"`
	Category                string                     `json:"category,omitempty"`
	MaxInputTokens          *int64                     `json:"max_input_tokens,omitempty"`
	ContextWindow           *int64                     `json:"context_window,omitempty"`
	ContextLimitKind        string                     `json:"context_limit_kind,omitempty"`
	MaxOutputTokens         *int64                     `json:"max_output_tokens,omitempty"`
	InputModalities         []string                   `json:"input_modalities,omitempty"`
	InputModalitiesStatus   string                     `json:"input_modalities_status,omitempty"`
	OutputModalities        []string                   `json:"output_modalities,omitempty"`
	Reasoning               *bool                      `json:"reasoning,omitempty"`
	ReasoningControl        *AccountReasoningControl   `json:"reasoning_control,omitempty"`
	SupportsFunctionCalling *bool                      `json:"supports_function_calling,omitempty"`
	SupportsPromptCaching   *bool                      `json:"supports_prompt_caching,omitempty"`
	Tools                   *AccountDeclaredTools      `json:"tools,omitempty"`
	EmbeddingDimensions     *int64                     `json:"embedding_dimensions,omitempty"`
	TaskLimits              map[string]json.RawMessage `json:"task_limits,omitempty"`
}

type AccountDeclaredTools struct {
	FunctionCalling *bool `json:"function_calling,omitempty"`
}

type AccountReasoningControl = service.ReasoningControl

func (m AccountModelCapabilitySpec) MarshalJSON() ([]byte, error) {
	type plain AccountModelCapabilitySpec
	return service.MarshalModelCapabilityLists(plain(m), map[string][]string{"input_modalities": m.InputModalities, "output_modalities": m.OutputModalities})
}

// SyncUpstreamModelsRequest allows a declaration draft only for a read-only preview.
// Applying a catalog always uses the declaration saved with the account rules.
type SyncUpstreamModelsRequest struct {
	Review                  *service.AccountCatalogReview `json:"review,omitempty"`
	ModelCapabilityDefaults json.RawMessage               `json:"model_capability_defaults"`
}

type SyncUpstreamModelsPreviewRequest struct {
	CredentialDraft         string            `json:"credential_draft"`
	CredentialDraftRevision string            `json:"credential_draft_revision"`
	ProxyID                 *int64            `json:"proxy_id"`
	Platform                string            `json:"platform" binding:"required"`
	Type                    string            `json:"type" binding:"required"`
	BaseURL                 string            `json:"base_url"`
	APIKey                  string            `json:"api_key"`
	Credentials             map[string]any    `json:"credentials"`
	ModelMapping            map[string]string `json:"model_mapping"`
	ModelCapabilityDefaults json.RawMessage   `json:"model_capability_defaults"`
}

func decodeModelCapabilityDefaults(raw json.RawMessage) (map[string]any, error) {
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
	if len(raw) > 1<<20 {
		return nil, fmt.Errorf("model_capability_defaults exceeds 1 MiB")
	}
	var declaration map[string]any
	if err := json.Unmarshal(raw, &declaration); err != nil || declaration == nil {
		return nil, fmt.Errorf("model_capability_defaults must be a JSON object")
	}
	var envelope AccountModelCapabilityDefaults
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&envelope); err != nil {
		return nil, fmt.Errorf("model_capability_defaults contains unknown fields or invalid field types")
	}
	if envelope.SchemaVersion != 1 || strings.TrimSpace(envelope.Reason) == "" || len(envelope.Reason) > 4096 || len(envelope.Models) == 0 || len(envelope.Models) > 1000 {
		return nil, fmt.Errorf("model_capability_defaults requires schema_version=1, a reason (1–4096 characters), and 1–1000 models")
	}
	models, ok := declaration["models"].(map[string]any)
	if !ok {
		return nil, fmt.Errorf("model_capability_defaults requires a models object")
	}
	for id, model := range envelope.Models {
		if _, ok := models[id].(map[string]any); !ok {
			return nil, fmt.Errorf("model_capability_defaults model %q must be an object", id)
		}
		if strings.TrimSpace(id) != id || id == "" || len(id) > 512 || strings.ContainsAny(id, "*?\r\n\t") {
			return nil, fmt.Errorf("model_capability_defaults requires exact, nonempty original model IDs without wildcards")
		}
		if err := validateAccountModelCapabilitySpec(model); err != nil {
			return nil, fmt.Errorf("model_capability_defaults model %q: %w", id, err)
		}
	}
	// Canonicalize JSON field names while preserving pointer-backed false/unknown.
	canonical, err := json.Marshal(envelope)
	if err != nil {
		return nil, fmt.Errorf("invalid model_capability_defaults")
	}
	declaration = nil
	if err := json.Unmarshal(canonical, &declaration); err != nil {
		return nil, fmt.Errorf("invalid model_capability_defaults")
	}
	return declaration, nil
}

func validateAccountModelCapabilitySpec(m AccountModelCapabilitySpec) error {
	for name, value := range map[string]*int64{"max_input_tokens": m.MaxInputTokens, "context_window": m.ContextWindow, "max_output_tokens": m.MaxOutputTokens, "embedding_dimensions": m.EmbeddingDimensions} {
		if value != nil && (*value <= 0 || *value > 1<<53-1) {
			return fmt.Errorf("%s must be a positive safe integer", name)
		}
	}
	if m.ContextLimitKind != "" && m.ContextLimitKind != "input" && m.ContextLimitKind != "total" {
		return fmt.Errorf("context_limit_kind must be input or total")
	}
	if m.MaxInputTokens != nil && m.ContextWindow != nil && m.ContextLimitKind == "input" && *m.MaxInputTokens != *m.ContextWindow {
		return fmt.Errorf("max_input_tokens conflicts with context_window marked as input")
	}
	if m.ContextWindow != nil && m.ContextLimitKind == "total" {
		if m.MaxOutputTokens != nil && *m.MaxOutputTokens > *m.ContextWindow || m.MaxInputTokens != nil && *m.MaxInputTokens > *m.ContextWindow {
			return fmt.Errorf("input/output limit exceeds total context_window")
		}
	}
	if m.InputModalitiesStatus != "" && m.InputModalitiesStatus != "complete" && m.InputModalitiesStatus != "partial" {
		return fmt.Errorf("input_modalities_status must be complete or partial")
	}
	for _, modalities := range [][]string{m.InputModalities, m.OutputModalities} {
		if len(modalities) > 32 {
			return fmt.Errorf("too many modalities")
		}
		for i, modality := range modalities {
			if modality == "" || modality != strings.TrimSpace(modality) || len(modality) > 64 || slices.Contains(modalities[:i], modality) {
				return fmt.Errorf("modalities must contain unique nonempty names")
			}
		}
	}
	if m.Tools != nil && m.Tools.FunctionCalling != nil && m.SupportsFunctionCalling != nil && *m.Tools.FunctionCalling != *m.SupportsFunctionCalling {
		return fmt.Errorf("tools.function_calling conflicts with supports_function_calling")
	}
	c := m.ReasoningControl
	if c == nil {
		return nil // Partial declarations retain missing-field diagnostics.
	}
	kinds := []string{"none", "effort", "toggle", "budget", "adaptive", "fixed", "unknown"}
	if !slices.Contains(kinds, c.Kind) {
		return fmt.Errorf("invalid reasoning_control.kind")
	}
	for i, kind := range c.SupportedKinds {
		if !slices.Contains(kinds, kind) || slices.Contains(c.SupportedKinds[:i], kind) {
			return fmt.Errorf("invalid or duplicate reasoning_control.supported_kinds")
		}
	}
	if len(c.SupportedKinds) > 0 && !slices.Contains(c.SupportedKinds, c.Kind) {
		return fmt.Errorf("reasoning_control.kind must belong to supported_kinds")
	}
	if m.Reasoning != nil && !*m.Reasoning {
		if c.Kind != "none" && c.Kind != "unknown" || len(c.EffortValues) > 0 || len(c.ToggleValues) > 0 || c.BudgetMin != nil || c.BudgetMax != nil || c.Adaptive != nil && *c.Adaptive {
			return fmt.Errorf("reasoning=false conflicts with reasoning_control")
		}
		for _, kind := range c.SupportedKinds {
			if kind != "none" && kind != "unknown" {
				return fmt.Errorf("reasoning=false conflicts with supported_kinds")
			}
		}
	}
	if m.Reasoning != nil && *m.Reasoning && c.Kind == "none" {
		return fmt.Errorf("reasoning=true conflicts with kind=none")
	}
	hasKind := func(kind string) bool { return c.Kind == kind || slices.Contains(c.SupportedKinds, kind) }
	if hasKind("effort") && len(c.EffortValues) == 0 || len(c.EffortValues) > 32 {
		return fmt.Errorf("effort control requires 1–32 actual effort_values")
	}
	for i, value := range c.EffortValues {
		if !hasKind("effort") || value == "" || len(value) > 64 || slices.Contains(c.EffortValues[:i], value) {
			return fmt.Errorf("invalid effort_values")
		}
	}
	if c.BudgetMin != nil && (*c.BudgetMin < 0 || *c.BudgetMin > 1<<53-1) || c.BudgetMax != nil && (*c.BudgetMax <= 0 || *c.BudgetMax > 1<<53-1) {
		return fmt.Errorf("reasoning budget must be a nonnegative minimum and positive maximum safe integer")
	}
	if c.BudgetMin != nil && c.BudgetMax != nil && *c.BudgetMin > *c.BudgetMax {
		return fmt.Errorf("reasoning budget minimum exceeds maximum")
	}
	if hasKind("budget") && (c.BudgetMin == nil || c.BudgetMax == nil) || !hasKind("budget") && (c.BudgetMin != nil || c.BudgetMax != nil) {
		return fmt.Errorf("budget control requires budget_min and budget_max")
	}
	if len(c.ToggleValues) > 0 && !hasKind("toggle") || c.Adaptive != nil && !hasKind("adaptive") {
		return fmt.Errorf("control options do not match supported kinds")
	}
	if len(c.ToggleValues) > 2 || len(c.ToggleValues) == 2 && c.ToggleValues[0] == c.ToggleValues[1] {
		return fmt.Errorf("toggle_values must contain unique booleans")
	}
	if len(c.Default) > 0 {
		switch c.Kind {
		case "effort":
			var value string
			if json.Unmarshal(c.Default, &value) != nil || !slices.Contains(c.EffortValues, value) {
				return fmt.Errorf("default must be an actual effort value")
			}
		case "toggle":
			var value *bool
			if json.Unmarshal(c.Default, &value) != nil || value == nil || len(c.ToggleValues) > 0 && !slices.Contains(c.ToggleValues, *value) {
				return fmt.Errorf("default must be a supported toggle boolean")
			}
		case "budget":
			var value *int64
			if json.Unmarshal(c.Default, &value) != nil || value == nil || *value < *c.BudgetMin || *value > *c.BudgetMax {
				return fmt.Errorf("default must fall within the budget range")
			}
		default:
			return fmt.Errorf("default is only valid for effort, toggle, or budget controls")
		}
	}
	return nil
}

// This fingerprint follows catalog identity fields without exposing credentials.
// Stable subjects make OAuth token refreshes independent of deployment identity.
func modelCapabilityIdentityFingerprint(account *service.Account) string {
	return service.ModelCapabilityIdentityFingerprint(account)
}

func bindModelCapabilityDefaults(account *service.Account, extra map[string]any, actor string) error {
	value, exists := extra[modelCapabilityDefaultsKey]
	if !exists || value == nil {
		return nil
	}
	raw, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("invalid model_capability_defaults")
	}
	declaration, err := decodeModelCapabilityDefaults(raw)
	if err != nil || declaration == nil {
		return err
	}
	identityAccount := *account
	identityAccount.Credentials = maps.Clone(account.Credentials)
	if err := service.NormalizeHeaderOverrideCredentials(identityAccount.Credentials); err != nil {
		return fmt.Errorf("model_capability_defaults cannot bind invalid account header overrides")
	}
	if err := service.NormalizeOpenCodeGoProtocolRulesCredentials(identityAccount.Credentials); err != nil {
		return fmt.Errorf("model_capability_defaults cannot bind invalid account protocol rules")
	}
	identityAccount.Credentials = service.SanitizeStoredCredentials(account.Platform, identityAccount.Credentials)
	fingerprint := modelCapabilityIdentityFingerprint(&identityAccount)
	revision := strconv.FormatInt(account.ModelCatalogBaseline().IdentityRevision, 10)
	if previous, _ := declaration["identity_fingerprint"].(string); previous != "" && (previous != fingerprint || declaration["identity_revision"] != revision) {
		return fmt.Errorf("model_capability_defaults belongs to a different account identity; verify deployment facts and remove identity_fingerprint to reconfirm")
	}
	declaration["identity_fingerprint"] = fingerprint
	declaration["identity_revision"] = revision
	declaration["confirmed_by"] = actor
	declaration["confirmed_at"] = time.Now().UTC().Format(time.RFC3339Nano)
	extra[modelCapabilityDefaultsKey] = declaration
	return nil
}

func prepareUpdatedModelCapabilityDefaults(existing *service.Account, accountType string, credentials, extra map[string]any, actor string) error {
	if extra[modelCapabilityDefaultsKey] == nil {
		return nil
	}
	next := *existing
	if accountType != "" {
		next.Type = accountType
	}
	if len(credentials) > 0 {
		next.Credentials = service.MergePreservingSensitiveCreds(existing.Credentials, credentials)
		if err := service.NormalizeHeaderOverrideCredentials(next.Credentials); err != nil {
			return fmt.Errorf("invalid account header overrides")
		}
		if err := service.NormalizeOpenCodeGoProtocolRulesCredentials(next.Credentials); err != nil {
			return fmt.Errorf("invalid account protocol rules")
		}
		next.Credentials = service.SanitizeStoredCredentials(next.Platform, next.Credentials)
	}
	next.Extra = maps.Clone(existing.Extra)
	service.AdvanceAccountModelCatalogRevisionsForUpdate(existing, &next, true)
	before, _ := json.Marshal(existing.Extra[modelCapabilityDefaultsKey])
	incoming, _ := json.Marshal(extra[modelCapabilityDefaultsKey])
	if err := bindModelCapabilityDefaults(&next, extra, actor); err != nil {
		return err
	}
	if bytes.Equal(before, incoming) {
		// Saving unrelated fields is not a new holder confirmation.
		extra[modelCapabilityDefaultsKey] = existing.Extra[modelCapabilityDefaultsKey]
	}
	return nil
}

func validateSavedModelCapabilityIdentity(account *service.Account) error {
	value := account.Extra[modelCapabilityDefaultsKey]
	if value == nil {
		return nil
	}
	raw, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("invalid saved model_capability_defaults")
	}
	declaration, err := decodeModelCapabilityDefaults(raw)
	if err != nil || declaration == nil {
		return err
	}
	if declaration["identity_fingerprint"] != modelCapabilityIdentityFingerprint(account) || declaration["identity_revision"] != strconv.FormatInt(account.ModelCatalogBaseline().IdentityRevision, 10) {
		return fmt.Errorf("saved model_capability_defaults identity is stale or unbound; verify and save the deployment declaration again")
	}
	return nil
}

func validateModelCapabilityDefaultsExtra(extra map[string]any) error {
	value, exists := extra["model_capability_defaults"]
	if !exists {
		return nil
	}
	raw, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("model_capability_defaults must be a JSON object")
	}
	_, err = decodeModelCapabilityDefaults(raw)
	return err
}
